package com.DamnLol.ChasmSigil;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("chasmoffiresigil")
public interface ChasmSigilConfig extends Config
{
    @ConfigItem(
            keyName = "killCount",
            name = "Kill Count",
            description = "Current KC",
            hidden = true
    )
    default int killCount() { return 0; }

    @ConfigItem(
            keyName = "activeSigilName",
            name = "Active Sigil",
            description = "Last active sigil",
            hidden = true
    )
    default String activeSigilName() { return Sigil.UNKNOWN.name(); }

    @ConfigItem(
            keyName = "resetSize",
            name = "Reset overlay size",
            description = "reset overlay tests",
            hidden = true //testing resets
    )
    default boolean resetSize() { return false; }
}

package com.DamnLol.ChasmSigil;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class ChasmSigilOverlay extends Overlay
{
    // Base layout
    private static final float BASE_ICON = 62f;
    private static final float BASE_PAD = 8f;
    private static final float BASE_TEXT_W = 150f;
    private static final float BASE_W = BASE_PAD + BASE_ICON + BASE_PAD + BASE_TEXT_W + BASE_PAD + BASE_ICON + BASE_PAD;
    private static final float BASE_H = BASE_ICON + BASE_PAD * 2f;
    private static final float BASE_NAME = 15f;
    private static final float BASE_DESC = 13f;
    private static final float BASE_CNT = 20f;

    private static final int YELLOW_AT = 32;
    private static final int RED_AT = 65;

    private static final Color BG = new Color(20, 4, 4, 220);
    private static final Color BORDER = new Color(100, 20, 20, 255);
    private static final Color NAME_COL = new Color(175, 135, 2);
    private static final Color DESC_COL = new Color( 70, 210, 210);
    private static final Color COUNT_GREEN = new Color(0, 210, 0);
    private static final Color COUNT_YELLOW = new Color(255, 210, 0);
    private static final Color COUNT_RED = new Color(220, 30, 30);

    private final ChasmSigilPlugin plugin;

    private final BufferedImage[] sigilImages = new BufferedImage[Sigil.values().length];
    private BufferedImage counterBg = null;

    @Inject
    public ChasmSigilOverlay(ChasmSigilPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.MED);
        setMovable(true);
        setResizable(true);
        setSnappable(true);
        setMinimumSize(160);
        setPreferredSize(new Dimension((int) BASE_W, (int) BASE_H));
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!plugin.isInChasm()) return null;

        Sigil sigil = plugin.getActiveSigil();
        int killCount = plugin.getKillCount();


        if (sigil == Sigil.UNKNOWN) return null;

        // Scale everything uniformly
        Dimension pref = getPreferredSize();
        int prefW = (pref != null && pref.width > 0) ? pref.width : (int) BASE_W;
        float s = prefW / BASE_W;

        int icon = round(BASE_ICON * s);
        int pad = round(BASE_PAD * s);
        int width = round(BASE_W * s);
        int height = round(BASE_H * s);
        int nameSz = Math.max(8, round(BASE_NAME * s));
        int descSz = Math.max(7, round(BASE_DESC * s));
        int cntSz = Math.max(9, round(BASE_CNT * s));

        setPreferredSize(new Dimension(width, height));

        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

        g.setColor(BG);
        g.fillRoundRect(0, 0, width, height, 6, 6);
        g.setColor(BORDER);
        g.drawRoundRect(0, 0, width - 1, height - 1, 6, 6);

        int iconY = (height - icon) / 2;

        int sigilX = pad;
        int counterX = width - pad - icon;
        int textLeft = sigilX + icon + pad;
        int textW = counterX - pad - textLeft;

        // sigil
        BufferedImage sigImg = getSigilImage(sigil.ordinal());
        if (sigImg != null)
            g.drawImage(sigImg, sigilX, iconY, icon, icon, null);

        if (counterBg == null)
            counterBg = loadImage("/counter.png");
        if (counterBg != null)
            g.drawImage(counterBg, counterX, iconY, icon, icon, null);

        String str = String.valueOf(Math.min(killCount, 999));
        int sz = str.length() >= 3 ? Math.max(8, round(cntSz * 0.75f)) : cntSz;
        Font cntFont = new Font("Arial", Font.BOLD, sz);
        g.setFont(cntFont);
        FontMetrics fm = g.getFontMetrics();
        Color col = killCount >= RED_AT ? COUNT_RED
                : killCount >= YELLOW_AT ? COUNT_YELLOW
                : COUNT_GREEN;
        java.awt.geom.Rectangle2D bounds = fm.getStringBounds(str, g);
        int numX = counterX + (int) Math.round((icon - bounds.getWidth()) / 2.0);
        int numY = iconY + (icon + fm.getAscent() - fm.getDescent()) / 2;
        g.setColor(Color.BLACK);
        g.drawString(str, numX + 1, numY + 1);
        g.setColor(col);
        g.drawString(str, numX, numY);

        String name = sigil.getContractName();
        String desc = sigil.getDescription();

        // Contract name
        Font nameFont = new Font("Arial", Font.BOLD, nameSz);
        g.setFont(nameFont);
        g.setColor(NAME_COL);
        FontMetrics nameFm = g.getFontMetrics();
        int nameX = textLeft + (textW - nameFm.stringWidth(name)) / 2;
        int nameY = pad + nameFm.getAscent();
        g.drawString(name, nameX, nameY);
        g.setStroke(new BasicStroke(1f));
        g.drawLine(nameX, nameY + 2, nameX + nameFm.stringWidth(name), nameY + 2);

        // Kill style
        Font descFont = new Font("Arial", Font.PLAIN, descSz);
        g.setFont(descFont);
        g.setColor(DESC_COL);
        FontMetrics descFm = g.getFontMetrics();
        int descX = textLeft + (textW - descFm.stringWidth(desc)) / 2;
        int descY = height - pad - descFm.getDescent() - round(height * 0.08f);
        g.drawString(desc, descX, descY);

        return new Dimension(width, height);
    }

    public void resetSize()
    {
        setPreferredSize(new Dimension((int) BASE_W, (int) BASE_H));
    }

    private static int round(float v) { return Math.round(v); }

    private BufferedImage getSigilImage(int ord)
    {
        if (sigilImages[ord] == null)
            sigilImages[ord] = loadImage("/sigil" + (ord + 1) + ".png");
        return sigilImages[ord];
    }

    private BufferedImage loadImage(String path)
    {
        try (InputStream in = getClass().getResourceAsStream(path))
        {
            if (in == null) return null;
            return ImageIO.read(in);
        }
        catch (IOException e)
        {
            return null;
        }
    }
}

package com.DamnLol.ChasmSigil;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NpcID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.HashSet;
import java.util.Set;

@Slf4j
@PluginDescriptor(
        name = "Chasm Sigils",
        description = "Information on current Sigil in the Chasm of Fire.",
        tags = {"chasm", "chasm of fire", "demon", "sigil", "contract", "pvm", "slayer"}
)
public class ChasmSigilPlugin extends Plugin
{
    private static final String CONFIG_GROUP = "chasmoffiresigil";
    private static final String KEY_KILLS = "killCount";
    private static final String KEY_SIGIL = "activeSigilName";

    private static final int[] CHASM_REGIONS = {5789, 5790, 5277, 5278};

    private static final int[] DEMON_IDS = {
            7656, 7657, 7664,
            NpcID.GREATER_DEMON, 2030, 2031, 2032,
            NpcID.BLACK_DEMON, 240, 5874, 5875, 5876, 5877,
    };

    static final int GRAPHIC_RED = 6400;
    static final int GRAPHIC_YELLOW = 6401;
    static final int GRAPHIC_GREEN = 6402;
    static final int GRAPHIC_PURPLE = 6403;
    static final int GRAPHIC_BLUE = 6404;

    @Inject private Client client;
    @Inject private OverlayManager overlayManager;
    @Inject private ChasmSigilOverlay overlay;
    @Inject private ConfigManager configManager;

    @Getter private Sigil activeSigil = Sigil.UNKNOWN;
    @Getter private boolean inChasm = false;
    @Getter private int killCount = 0;

    private final Set<Integer> damagedByPlayer = new HashSet<>();
    private boolean stateLoaded = false;

    @Provides
    ChasmSigilConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ChasmSigilConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        stateLoaded = false;
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            loadSavedState();
            stateLoaded = true;
        }
    }

    @Override
    protected void shutDown()
    {
        saveState();
        overlayManager.remove(overlay);
        activeSigil = Sigil.UNKNOWN;
        inChasm = false;
        stateLoaded = false;
        damagedByPlayer.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals(CONFIG_GROUP)) return;
        if (!event.getKey().equals("resetSize")) return;
        overlay.resetSize();
        configManager.setConfiguration(CONFIG_GROUP, "resetSize", false);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        //keep previous sigil/kc data
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN && !stateLoaded)
        {
            loadSavedState();
            stateLoaded = true;
        }
        else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
        {
            saveState();
            stateLoaded = false;
            inChasm = false;
            activeSigil = Sigil.UNKNOWN;
            damagedByPlayer.clear();
        }
        else if (state == GameState.LOADING)
        {
            inChasm = false;
            damagedByPlayer.clear();
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (!inChasm) return;
        if (!(event.getActor() instanceof NPC)) return;
        NPC npc = (NPC) event.getActor();
        if (isNotDemon(npc)) return;
        if (!event.getHitsplat().isMine()) return;
        damagedByPlayer.add(npc.getIndex());
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        if (!inChasm) return;
        NPC npc = event.getNpc();
        if (isNotDemon(npc)) return;
        if (!npc.isDead()) return;
        if (!damagedByPlayer.remove(npc.getIndex())) return;
        killCount = Math.min(killCount + 1, 999); //counter max
        saveState();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        inChasm = checkInChasm();

        if (!inChasm)
            return;

        Sigil newSigil = scanDemonsForSigil();
        if (newSigil != Sigil.UNKNOWN)
        {
            if (newSigil != activeSigil)
            {
                killCount = 0;
                damagedByPlayer.clear();
                saveState();
            }
            activeSigil = newSigil;
        }
    }

    private void saveState()
    {
        if (!stateLoaded) return;
        configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_KILLS, killCount);
        configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_SIGIL, activeSigil.name());
    }

    private void loadSavedState()
    {
        String sigilName = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_SIGIL);
        String countStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_KILLS);

        activeSigil = Sigil.UNKNOWN;
        killCount = 0;

        if (sigilName != null)
        {
            try
            {
                Sigil saved = Sigil.valueOf(sigilName);
                if (saved != Sigil.UNKNOWN)
                {
                    activeSigil = saved;
                }
            }
            catch (IllegalArgumentException ignored) {}
        }

        if (countStr != null)
        {
            try { killCount = Integer.parseInt(countStr); }
            catch (NumberFormatException ignored) {}
        }
    }

    private boolean checkInChasm()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return false;
        int region = client.getLocalPlayer().getWorldLocation().getRegionID();
        for (int r : CHASM_REGIONS)
            if (r == region) return true;
        return false;
    }

    private Sigil scanDemonsForSigil()
    {
        for (NPC npc : client.getNpcs())
        {
            if (isNotDemon(npc)) continue;
            Sigil found = sigilFromOverhead(npc);
            if (found != Sigil.UNKNOWN) return found;
        }
        return Sigil.UNKNOWN;
    }

    private Sigil sigilFromOverhead(NPC npc)
    {
        int[] archiveIds = npc.getOverheadArchiveIds();
        short[] spriteIds = npc.getOverheadSpriteIds();
        if (archiveIds == null || spriteIds == null) return Sigil.UNKNOWN;

        for (int i = 0; i < archiveIds.length; i++)
        {
            if (archiveIds[i] == -1) continue;
            if (archiveIds[i] == GRAPHIC_RED) return Sigil.RED;
            if (archiveIds[i] == GRAPHIC_YELLOW) return Sigil.YELLOW;
            if (archiveIds[i] == GRAPHIC_GREEN) return Sigil.GREEN;
            if (archiveIds[i] == GRAPHIC_PURPLE) return Sigil.PURPLE;
            if (archiveIds[i] == GRAPHIC_BLUE) return Sigil.BLUE;
        }
        return Sigil.UNKNOWN;
    }

    private boolean isNotDemon(NPC npc)
    {
        int id = npc.getId();
        for (int did : DEMON_IDS)
            if (did == id) return false;
        String name = npc.getName();
        return name == null || (
                !name.equals("Lesser demon") &&
                        !name.equals("Greater demon") &&
                        !name.equals("Black demon")
        );
    }
}

package com.DamnLol.ChasmSigil;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
@Getter
public enum Sigil
{
    GREEN ("Divine Severance", "Heavy ranged weapon"),
    BLUE  ("Sensory Clouding", "Spell (Not Powered)"),
    YELLOW("Glyphic Attenuation", "Special attack"),
    RED   ("Bloodied Blows", "Two-handed melee"),
    PURPLE("Forfeit Breath", "Kill demon when bound"),
    UNKNOWN("", "");

    private final String contractName;
    private final String description;
}

package com.DamnLol;

import com.DamnLol.ChasmSigil.ChasmSigilPlugin;
